"""Reconstructible source helpers. Not World semantics. No persistent Source IR."""

from __future__ import annotations

import csv
import hashlib
import json
from collections import Counter, defaultdict
from pathlib import Path
from typing import Any

from ontology_author.world.core.source import AssertionGrounding, SourceObservation

_STRUCTURED = {".csv", ".json"}


def looks_numeric(value: Any) -> bool:
    text = str(value or "").strip().replace(",", "")
    if not text:
        return False
    try:
        float(text)
        return True
    except ValueError:
        return False


class Source:
    def __init__(self, root: str | Path = ".") -> None:
        self.root = Path(root)

    def _path(self, name: str) -> Path:
        """Resolve an evidence path relative to the ordinary project tree."""

        return self.root / name

    def tables(self) -> list[str]:
        if not self.root.exists():
            return []
        names: set[str] = set()
        for directory in [self.root]:
            names.update(
                path.name
                for path in directory.iterdir()
                if path.is_file() and path.suffix.lower() in _STRUCTURED
            )
        return sorted(names)

    def _load(self, table: str) -> list[dict[str, Any]]:
        path = self._path(table)
        if not path.exists():
            raise FileNotFoundError(table)
        if path.suffix.lower() == ".json":
            payload = json.loads(path.read_text(encoding="utf-8"))
            if isinstance(payload, list):
                return [row if isinstance(row, dict) else {"value": row} for row in payload]
            if isinstance(payload, dict):
                return [payload]
            return []
        with path.open(encoding="utf-8", newline="") as handle:
            return list(csv.DictReader(handle))

    def rows(self, table: str) -> list[dict[str, Any]]:
        return self._load(table)

    def fields(self, table: str) -> list[str]:
        rows = self._load(table)
        if not rows:
            return []
        return list(rows[0].keys())

    def profile(self, table: str, field: str) -> dict[str, Any]:
        rows = self._load(table)
        values = ["" if row.get(field) is None else str(row.get(field)) for row in rows]
        nonempty = [value for value in values if value.strip()]
        return {
            "table": table,
            "field": field,
            "n": len(values),
            "n_empty": len(values) - len(nonempty),

