"""Filesystem discovery for project-local Worlds.

There is deliberately no registry: a World is a directory under ``.worlds``
whose sealed ``world/`` bundle contains ``world.sqlite``.
"""

from __future__ import annotations

import re
from dataclasses import dataclass
from pathlib import Path

WORLD_DIR = ".worlds"
_NAME = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$")


class WorldSelectionError(ValueError):
    """A requested World cannot be selected unambiguously."""


@dataclass(frozen=True)
class WorldRef:
    name: str
    path: Path

    @property
    def world(self) -> Path:
        return self.path / "world" / "world.sqlite"


def project_root(path: Path | str = ".") -> Path:
    return Path(path).expanduser().resolve()


def validate_name(name: str) -> str:
    value = str(name or "").strip()
    if not _NAME.fullmatch(value):
        raise WorldSelectionError(
            "World name must start with a letter or number and contain only "
            "letters, numbers, '.', '_' or '-'."
        )
    return value


def world_ref(project: Path | str, name: str) -> WorldRef:
    root = project_root(project)
    safe = validate_name(name)
    return WorldRef(safe, root / WORLD_DIR / safe)


def discover(project: Path | str = ".") -> list[WorldRef]:
    root = project_root(project) / WORLD_DIR
    if not root.is_dir():
        return []
    return [
        WorldRef(item.name, item)
        for item in sorted(root.iterdir(), key=lambda item: item.name.lower())
        if item.is_dir() and _NAME.fullmatch(item.name) and (item / "world" / "world.sqlite").exists()
    ]


def select(project: Path | str = ".", name: str | None = None) -> WorldRef:
    if name:
        selected = world_ref(project, name)
        if not selected.world.exists():
            raise WorldSelectionError(
                f"World {selected.name!r} has not been built; rebuild it first"
            )
        return selected
    worlds = discover(project)
    if len(worlds) == 1:
        return worlds[0]
    if not worlds:
        raise WorldSelectionError(
            f"no Worlds found under {project_root(project) / WORLD_DIR}"
        )
    names = ", ".join(item.name for item in worlds)
    raise WorldSelectionError(f"several Worlds exist; choose one: {names}")


__all__ = ["WORLD_DIR", "WorldRef", "WorldSelectionError", "discover", "project_root", "select", "validate_name", "world_ref"]

        "n_empty": len(values) - len(nonempty),
        "n_distinct": len(set(nonempty)),
        "n_numeric": sum(1 for value in nonempty if looks_numeric(value)),
        "sample_distinct": sorted(set(nonempty), key=lambda item: (len(item), item))[:25],
    }

def distinct_values(self, table: str, field: str, limit: int = 50) -> list[dict[str, Any]]:
    counts: Counter[str] = Counter()
    for row in self._load(table):
        counts[str(row.get(field) or "")] += 1
    return [{"value": value, "n": n} for value, n in counts.most_common(limit)]

def join(self, left: str, right: str, on: list[tuple[str, str]]) -> list[dict[str, Any]]:
    index: dict[tuple, list[dict[str, Any]]] = defaultdict(list)
    for row in self._load(right):
        key = tuple(str(row.get(right_field) or "") for _, right_field in on)
        index[key].append(row)
    out: list[dict[str, Any]] = []
    for left_row in self._load(left):
        key = tuple(str(left_row.get(left_field) or "") for left_field, _ in on)
        for right_row in index.get(key, []):
            merged = {f"l.{key_}": value for key_, value in left_row.items()}
            merged.update({f"r.{key_}": value for key_, value in right_row.items()})
            out.append(merged)
    return out

def read_text(self, name: str) -> str:
    return self._path(name).read_text(encoding="utf-8")

def file_hash(self, name: str) -> str:
    return hashlib.sha256(self._path(name).read_bytes()).hexdigest()

def observation(self, table: str, location: str) -> SourceObservation:
    return SourceObservation(
        provider="file",
        native_handle=table,
        source_revision=self.file_hash(table),
        native_location=location,
    )

def grounding(
    self,
    table: str,
    location: str,
    *,
    method: str = "",
    extra: dict[str, Any] | None = None,
) -> AssertionGrounding:
    return AssertionGrounding(
        observations=(self.observation(table, location),),
        construction_method=method,
        extra=extra,
    )

