for data in structures:
    for indent in [None, 2, 4]:
        for sort in [False, True]:
            payload = data
            if sort and isinstance(payload, dict):
                payload = {k: sorted(v, key=lambda x: list(x.values())[0]) if isinstance(v, list) else v for k,v in data.items()}
            s = json.dumps(payload, indent=indent, sort_keys=sort)
            h = hashlib.sha256(s.encode()).hexdigest()
            if h == TARGET:
